#!/bin/sh
#
# voxel-up.sh: install a build of voxel into ./.voxel and point voxel at it.
#
# Generated by `cargo xtask voxel-up` for voxel @VOXEL_REV@.
#
#   curl -sSfL <url>/voxel-up.sh | sh             # this commit's CI build
#   sh voxel-up.sh --archive out/dist/voxel.tar.gz # a local `cargo xtask dist`
#   curl -sSfL <url>/voxel-up.sh | sh -s -- --archive voxel.tar.gz
#
# A local archive is checked against <archive>.sha256.txt when that exists.
#
# Overrides, from the environment:
#   VOXEL_ARCHIVE   same as --archive
#   VOXEL_REV       voxel commit whose CI artifacts to fetch (full sha)
#   VOXEL_BASE_URL  buildomat release series the artifacts are published under
#   VOXEL_POOL      zfs pool for falcon's dataset (default: fpool if it
#                   exists, else rpool)
#
# Everything lands in ./.voxel:
#   .voxel/bin/       voxel, voxel-init, voxel-init-linux, sp-emu
#   .voxel/voxel.toml config: dataset, workdir, build root, sp-emu
#   .voxel/env        source it to put voxel on PATH and select the config
#
# The body is one function called on the last line, so a truncated download
# runs nothing.

voxel_up() {
	set -eu

	rev="${VOXEL_REV:-@VOXEL_REV@}"
	base="${VOXEL_BASE_URL:-@VOXEL_BASE_URL@}"
	url="$base/$rev"
	archive="${VOXEL_ARCHIVE:-}"

	say() { printf 'voxel-up: %s\n' "$*" >&2; }
	die() { say "error: $*"; exit 1; }

	while [ $# -gt 0 ]; do
		case "$1" in
		--archive)
			[ $# -ge 2 ] || die "--archive needs a path"
			archive="$2"
			shift 2
			;;
		--archive=*)
			archive="${1#--archive=}"
			shift
			;;
		-h | --help)
			cat <<-EOF
			usage: voxel-up.sh [--archive FILE]

			Install voxel into ./.voxel and write ./.voxel/voxel.toml.
			Without --archive, fetches the CI build of $rev from
			$base.
			With --archive, installs a local voxel.tar.gz (from
			\`cargo xtask dist\`), checked against FILE.sha256.txt if present.

			Environment: VOXEL_ARCHIVE, VOXEL_REV, VOXEL_BASE_URL, VOXEL_POOL
			EOF
			exit 0
			;;
		*) die "unknown argument: $1 (usage: voxel-up.sh [--archive FILE])" ;;
		esac
	done

	[ "$(uname -s)" = SunOS ] ||
		die "voxel runs on a Helios (illumos) host, not $(uname -s)"
	if [ -n "$archive" ]; then
		[ -f "$archive" ] || die "no archive at $archive"
		case "$archive" in
		/*) ;;
		*) archive="$(pwd)/$archive" ;;
		esac
	else
		command -v curl >/dev/null 2>&1 || die "curl not found"
	fi

	# falcon's dataset: a dedicated fpool when the host has one, else rpool.
	if [ -n "${VOXEL_POOL:-}" ]; then
		pool="$VOXEL_POOL"
	elif zpool list -H -o name fpool >/dev/null 2>&1; then
		pool=fpool
	else
		pool=rpool
	fi
	zpool list -H -o name "$pool" >/dev/null 2>&1 ||
		die "zfs pool $pool does not exist"
	say "using zfs pool $pool"

	root="$(pwd)/.voxel"
	bin="$root/bin"
	mkdir -p "$bin"

	sha256() {
		if command -v digest >/dev/null 2>&1; then
			digest -a sha256 "$1"
		else
			sha256sum "$1" | awk '{print $1}'
		fi
	}

	# Stage and verify the bundle before touching anything already installed.
	tmp="$(mktemp -d "$root/.dl.XXXXXX")"
	trap 'rm -rf "$tmp"' EXIT
	if [ -n "$archive" ]; then
		what="$archive"
		say "installing $archive"
		cp "$archive" "$tmp/voxel.tar.gz"
		if [ -f "$archive.sha256.txt" ]; then
			cp "$archive.sha256.txt" "$tmp/voxel.tar.gz.sha256.txt"
		else
			say "no $archive.sha256.txt; installing unverified"
		fi
	else
		what="voxel $rev"
		say "fetching voxel $rev"
		curl -sSfL --retry 5 -o "$tmp/voxel.tar.gz" "$url/voxel.tar.gz" ||
			die "download failed: $url/voxel.tar.gz (has CI finished for $rev?)"
		curl -sSfL --retry 5 -o "$tmp/voxel.tar.gz.sha256.txt" \
			"$url/voxel.tar.gz.sha256.txt" ||
			die "download failed: $url/voxel.tar.gz.sha256.txt"
	fi
	if [ -f "$tmp/voxel.tar.gz.sha256.txt" ]; then
		want="$(awk '{print $1}' "$tmp/voxel.tar.gz.sha256.txt")"
		got="$(sha256 "$tmp/voxel.tar.gz")"
		[ "$want" = "$got" ] ||
			die "voxel.tar.gz sha256 mismatch: want $want, got $got"
	fi

	(cd "$tmp" && gzip -dc voxel.tar.gz | tar xf -)
	for f in voxel voxel-init voxel-init-linux sp-emu; do
		[ -f "$tmp/$f" ] || die "voxel.tar.gz has no $f"
		chmod 755 "$tmp/$f"
		mv -f "$tmp/$f" "$bin/$f"
	done
	say "installed voxel, voxel-init, voxel-init-linux, sp-emu in $bin"

	# A config of its own, so this install never edits ~/.config/voxel.
	# falcon state, image builds and the omicron build root all stay under
	# .voxel; images go in the pool's shared falcon dataset.
	config="$root/voxel.toml"
	set_cfg() { VOXEL_CONFIG="$config" "$bin/voxel" config set "$1" "$2" >/dev/null; }
	set_cfg falcon.dataset "$pool/falcon"
	set_cfg falcon.workdir "$root"
	set_cfg falcon.build_root "$root/builds"
	set_cfg sp.emu_bin "$bin/sp-emu"

	cat >"$root/env" <<-EOF
	# Source this file to use the voxel in $root.
	export PATH="$bin:\$PATH"
	export VOXEL_CONFIG="$config"
	EOF

	cat >&2 <<-EOF

	$what is ready in $root.

	  . $root/env
	  voxel config show

	CI does not publish rack images. Build them once per host (pfexec keeps
	VOXEL_CONFIG, so they land in $pool/falcon):

	  pfexec voxel image create-frr proto
	  pfexec voxel image create
	  voxel image ls
	  voxel config set image.frr voxel-frr-proto
	  voxel config set image.cp voxel-cp-<hash>
	  pfexec voxel launch
	EOF
}

voxel_up "$@"
